package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Descriptive field help text is omitted; Apex assertions and functional metadata
// are preserved. The maintenance fixture retains the complete source for CLI replay.
func TestRunParentLevelContracts(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeParentPath53.cls"), "@IsTest private class GladeParentPath53 {\n    public static List<String> getOwnerIdPath(SObjectType t) {\n        List<String> result = new List<String>();\n        DescribeSObjectResult obj = t.getDescribe();\n        Map<String, Schema.SObjectField> fieldMap = obj.fields.getMap();\n        if(fieldMap.containsKey('OwnerId')) {\n            result.add('OwnerId');\n            return result;\n        }\n        if(fieldMap.containsKey('ParentId')) {\n            result.add('Parent');\n            result.addAll(getOwnerIdPath(fieldMap.get('ParentId').getDescribe().getReferenceTo()[0]));\n            return result;\n        }\n        for(Schema.SObjectField f : fieldMap.values()) {\n            Schema.DescribeFieldResult dfr = f.getDescribe();\n            List <Schema.sObjectType> refs = dfr.getReferenceTo();\n            if(refs.size() > 0 && dfr.getRelationshipOrder() == 0 ) {\n                result.add(dfr.getRelationshipName());\n                result.addAll(getOwnerIdPath(refs[0]));\n                break;\n            }\n        }\n        return result;\n    }\n@IsTest static void directOwnerControl(){System.assertEquals(new List<String>{'OwnerId'},getOwnerIdPath(Opportunity.SObjectType),'original direct owner path');}\n@IsTest static void masterDetailOwnerPath(){\nMap<String,Schema.SObjectField> fields=GladeOwnedDetail53__c.SObjectType.getDescribe().fields.getMap();\nSystem.assertEquals(false,fields.containsKey('OwnerId'),'master detail child has no direct OwnerId');\nSchema.DescribeFieldResult parent=GladeOwnedDetail53__c.GladeAccount__c.getDescribe();\nSystem.assertEquals(0,parent.getRelationshipOrder(),'primary master relationship');\nSystem.assertEquals(new List<Schema.SObjectType>{Account.SObjectType},parent.getReferenceTo(),'Account parent');\nSystem.assertEquals('GladeAccount__r',parent.getRelationshipName(),'owned parent relationship');\nSystem.assertEquals(new List<String>{'GladeAccount__r','OwnerId'},getOwnerIdPath(GladeOwnedDetail53__c.SObjectType),'original parent owner path shape');\n}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeParentPath53.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeLevelValidation53.cls"), "public class GladeLevelValidation53 {\npublic void run(List<GladeLevelProbe53__c> incoming){\nMap<String,List<GladeLevelProbe53__c>> ladders=new Map<String,List<GladeLevelProbe53__c>>();\nSet<GladeLevelProbe53__c> setTrigger=new Set<GladeLevelProbe53__c>();\nfor(GladeLevelProbe53__c lvl:incoming){setTrigger.add(lvl);List<GladeLevelProbe53__c> levels=getListLevel(ladders,'same-original-ladder');addLevel(lvl,levels);}\nfor(List<GladeLevelProbe53__c> levels:ladders.values()){verifyNoOverlapListLvl(levels,setTrigger);verifyNoDuplicateNames(levels,setTrigger);}\n}\npublic static void checkEmptyMapAlias(){\nMap<String,List<GladeLevelProbe53__c>> ladders=new Map<String,List<GladeLevelProbe53__c>>();GladeLevelValidation53 helper=new GladeLevelValidation53();\nList<GladeLevelProbe53__c> first=getListLevel(ladders,'same-original-ladder');\nhelper.addLevel(new GladeLevelProbe53__c(Name='new',Minimum_Amount__c=10,Maximum_Amount__c=100),first);\nSystem.assertEquals(1,ladders.get('same-original-ladder').size(),'empty list returned then appended stays in map');\nList<GladeLevelProbe53__c> second=getListLevel(ladders,'same-original-ladder');helper.addLevel(new GladeLevelProbe53__c(Name='new3',Minimum_Amount__c=5,Maximum_Amount__c=75),second);\nSystem.assertEquals(2,first.size(),'alias sees indexed insertion');System.assertEquals('new3',first[0].Name,'indexed insertion position');\nList<List<GladeLevelProbe53__c>> values=ladders.values();System.assertEquals(1,values.size(),'one ladder');System.assertEquals(2,values[0].size(),'map values sees original list mutations');\n}\n    private static list<GladeLevelProbe53__c> getListLevel(map<String, list<GladeLevelProbe53__c>> mapLadderToLevels, string strLadder) {\n        list<GladeLevelProbe53__c> listLvl = mapLadderToLevels.get(strLadder);\n        if (listLvl == null) {\n            listLvl = new list<GladeLevelProbe53__c>();\n            mapLadderToLevels.put(strLadder, listLvl);\n        }\n        return listLvl;\n    }\n    private void addLevel(GladeLevelProbe53__c lvl, list<GladeLevelProbe53__c> listLvl) {\n        \n        for (integer i = 0; i < listLvl.size(); i++) {\n            if (lvl.Minimum_Amount__c == null || lvl.Minimum_Amount__c <= listLvl[i].Minimum_Amount__c) {\n                listLvl.add(i, lvl);\n                return;\n            }\n        }\n        listLvl.add(lvl);\n    }\n    private void verifyNoOverlapListLvl(list<GladeLevelProbe53__c> listLvl, Set<GladeLevelProbe53__c> setTrigger) {\n        \n        for (integer i = 1; i < listLvl.size(); i++) {\n            // test overlapping ranges between levels\n            if ((listLvl[i].Minimum_Amount__c == null || listLvl[i-1].Minimum_Amount__c >= listLvl[i].Minimum_Amount__c) ||\n                (listLvl[i-1].Maximum_Amount__c == null || listLvl[i-1].Maximum_Amount__c > listLvl[i].Minimum_Amount__c)) {\n                integer ierr = setTrigger.contains(listLvl[i-1]) ? i-1 : i;\n                listLvl[ierr].addError(String.format('Overlap {0} {1}', new list<String>{listLvl[i-1].Name, listLvl[i].Name}));\n            }\n        }\n                    \n        for (integer i = 0; i < listLvl.size(); i++) {\n            // test min/max overlap within a level\n            if (listLvl[i].Minimum_Amount__c >= listLvl[i].Maximum_Amount__c) {\n                listLvl[i].addError(String.format('Minimum above maximum {0}', new list<String>{listLvl[i].Name}));                \n            }\n            \n        }\n    }\n    private void verifyNoDuplicateNames(list<GladeLevelProbe53__c> listLvl, Set<GladeLevelProbe53__c> setTrigger) {\n        \n        // track how many times each name is used\n        boolean hasDupe = false;\n        Map<String, Integer> mapNameToCount = new Map<String, Integer>();\n        for (GladeLevelProbe53__c lvl : listLvl) {\n            integer c = mapNameToCount.get(lvl.Name);\n            if (c == null) {\n                c = 1;\n            } else {\n                c++;\n                hasDupe = true;\n            }\n            mapNameToCount.put(lvl.Name, c);\n        }\n\n        // if dupe detected, find the one from the trigger that caused it\n        if (hasDupe) {\n            for (GladeLevelProbe53__c lvl : listLvl) {\n                if (setTrigger.contains(lvl) && mapNameToCount.get(lvl.Name) > 1) {\n                    lvl.addError(String.format('Duplicate name {0}', new list<String>{lvl.Name}));\n                }                \n            }\n        }\n    }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeLevelValidation53.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeLevelValidationTest53.cls"), "@IsTest private class GladeLevelValidationTest53 {\nprivate static GladeLevelProbe53__c level(String name,Decimal lo,Decimal hi){return new GladeLevelProbe53__c(Name=name,Minimum_Amount__c=lo,Maximum_Amount__c=hi);}\nprivate static void rejects(List<GladeLevelProbe53__c> rows,String expectedName){Boolean caught=false;Test.startTest();try{insert rows;}catch(DmlException ex){caught=true;System.assert(ex.getMessage().contains(expectedName),'original error includes level '+expectedName);}Test.stopTest();System.assert(caught,'original exception should have occurred');System.assertEquals(0,[SELECT COUNT() FROM GladeLevelProbe53__c],'all-or-none rejected batch leaves no rows');}\n@IsTest static void originalNewMin(){rejects(new List<GladeLevelProbe53__c>{level('new',10,100),level('new2',101,200),level('new3',50,75)},'new3');}\n@IsTest static void originalNewMax(){rejects(new List<GladeLevelProbe53__c>{level('new',10,100),level('new2',101,200),level('new3',5,75)},'new3');}\n@IsTest static void originalNewNames(){rejects(new List<GladeLevelProbe53__c>{level('new',10,100),level('new',101,200)},'new');}\n@IsTest static void originalMinMaxOverlap(){rejects(new List<GladeLevelProbe53__c>{level('new',101,100)},'new');}\n@IsTest static void emptyMapListAlias(){GladeLevelValidation53.checkEmptyMapAlias();}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeLevelValidationTest53.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/triggers/GladeLevelValidationTrigger53.trigger"), "trigger GladeLevelValidationTrigger53 on GladeLevelProbe53__c(before insert){new GladeLevelValidation53().run(Trigger.new);}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/triggers/GladeLevelValidationTrigger53.trigger-meta.xml"), "<ApexTrigger xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexTrigger>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeOwnedDetail53__c/GladeOwnedDetail53__c.object-meta.xml"), "<CustomObject xmlns=\"http://soap.sforce.com/2006/04/metadata\"><deploymentStatus>Deployed</deploymentStatus><label>Glade Owned Detail</label><nameField><label>Name</label><type>Text</type></nameField><pluralLabel>Glade Owned Detail Records</pluralLabel><sharingModel>ControlledByParent</sharingModel></CustomObject>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeLevelProbe53__c/GladeLevelProbe53__c.object-meta.xml"), "<CustomObject xmlns=\"http://soap.sforce.com/2006/04/metadata\"><deploymentStatus>Deployed</deploymentStatus><label>Glade Level Probe</label><nameField><label>Name</label><type>Text</type></nameField><pluralLabel>Glade Level Probe Records</pluralLabel><sharingModel>ReadWrite</sharingModel></CustomObject>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeOwnedDetail53__c/fields/GladeAccount__c.field-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<CustomField xmlns=\"http://soap.sforce.com/2006/04/metadata\">\n    <fullName>GladeAccount__c</fullName>\n    \n    <externalId>false</externalId>\n    \n    <label>Account</label>\n    <referenceTo>Account</referenceTo>\n    <relationshipLabel>Addresses</relationshipLabel>\n    <relationshipName>GladeOwnedDetails53</relationshipName>\n    <relationshipOrder>0</relationshipOrder>\n    <reparentableMasterDetail>true</reparentableMasterDetail>\n    <trackFeedHistory>false</trackFeedHistory>\n    <trackTrending>false</trackTrending>\n    <type>MasterDetail</type>\n    <writeRequiresMasterRead>true</writeRequiresMasterRead>\n</CustomField>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeLevelProbe53__c/fields/Minimum_Amount__c.field-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<CustomField xmlns=\"http://soap.sforce.com/2006/04/metadata\">\n    <fullName>Minimum_Amount__c</fullName>\n    \n    <externalId>false</externalId>\n    \n    <label>Minimum Amount (&gt;=)</label>\n    <precision>18</precision>\n    <required>false</required>\n    <scale>2</scale>\n    <trackHistory>false</trackHistory>\n    <trackTrending>false</trackTrending>\n    <type>Number</type>\n    <unique>false</unique>\n</CustomField>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeLevelProbe53__c/fields/Maximum_Amount__c.field-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<CustomField xmlns=\"http://soap.sforce.com/2006/04/metadata\">\n    <fullName>Maximum_Amount__c</fullName>\n    \n    <externalId>false</externalId>\n    \n    <label>Maximum Amount (&lt;)</label>\n    <precision>18</precision>\n    <required>false</required>\n    <scale>2</scale>\n    <trackHistory>false</trackHistory>\n    <trackTrending>false</trackTrending>\n    <type>Number</type>\n    <unique>false</unique>\n</CustomField>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\n  \"sourceApiVersion\": \"53.0\",\n  \"packageDirectories\": [\n    {\n      \"path\": \"force-app\",\n      \"default\": true\n    }\n  ]\n}\n")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 7 || got.Passed != 7 || got.Failed != 0 || got.Errors != 0 || got.Skipped != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("exact parent/level contracts failed: %s", data)
	}
}
